import { Lightning } from '@lightningjs/sdk';
export default class MenuItem extends Lightning.Component {
    static _template() {
        return {
            flexItem: { marginBottom: 50 },
            Icon: {
                x: -40,
                h: 40,
                w: 40,
                texture: Lightning.Tools.getSvgTexture('icons/movies.svg', 50, 50),
                color: 4294967295 /* Colors.WHITE */
            },
            h: 30,
            x: 40,
            mountY: 0.5,
            color: 4294967295 /* Colors.WHITE */,
            text: { text: 'Home', fontSize: 0, fontStyle: 'bold' }
        };
    }
    set label(v) {
        this._label = v;
        this.patch({
            text: { text: this._label }
        });
    }
    set collapsed(collapsed) {
        if (collapsed) {
            this.tag('Icon').setSmooth('h', 40);
            this.tag('Icon').setSmooth('w', 40);
            this.patch({
                h: 40,
                text: { fontSize: 0 }
            });
        }
        else {
            this.tag('Icon').setSmooth('h', 30);
            this.tag('Icon').setSmooth('w', 30);
            this.patch({
                h: 0,
                text: { fontSize: 25 }
            });
        }
    }
    set icon(icon) {
        this.patch({
            Icon: {
                texture: Lightning.Tools.getSvgTexture(`icons/${icon}.svg`, 30, 30)
            }
        });
    }
    set id(v) {
        this._id = v.replace(/ /g, '');
    }
    get id() {
        return this._id;
    }
    set selected(bool) {
        if (bool) {
            this.patch({
                Icon: { color: 4294293565 /* Colors.ACCENT */ },
                text: { textColor: 4294293565 /* Colors.ACCENT */, alpha: 0.6 }
            });
        }
        else {
            this.patch({
                Icon: { color: 4294967295 /* Colors.WHITE */ },
                text: { textColor: 4294967295 /* Colors.WHITE */, alpha: 1 }
            });
        }
        this._selected = bool;
    }
    get selected() {
        return this._selected;
    }
    _focus() {
        this.patch({
            Icon: { color: 4294293565 /* Colors.ACCENT */ },
            text: { textColor: 4294293565 /* Colors.ACCENT */ }
        });
    }
    _unfocus() {
        this.patch({
            Icon: { color: 4294967295 /* Colors.WHITE */ },
            text: { textColor: 4294967295 /* Colors.WHITE */ }
        });
    }
}
