import { Lightning, Router } from '@lightningjs/sdk';
import CollapsableLogo from '../logo/CollapsableLogo';
import MenuItem from './MenuItem';
export default class Menu extends Lightning.Component {
    static _template() {
        return {
            ShaderExtra: {
                h: 1080,
                w: 30,
                x: 70,
                rect: true,
                alpha: 0.8,
                color: 4280229156 /* Colors.SURFACE */,
                shader: { type: Lightning.shaders.FadeOut, right: 20 }
            },
            Wrapper: {
                w: 50,
                h: 1080,
                z: 1,
                rect: true,
                color: 4280229156 /* Colors.SURFACE */,
                alpha: 0.8,
                flex: {
                    direction: 'column',
                    paddingLeft: 20,
                    justifyContent: 'space-between',
                    alignContent: 'flex-start',
                    wrap: true
                },
                Logo: {
                    type: CollapsableLogo,
                    y: 50,
                    x: 25,
                    mountX: 0.5
                },
                MenuItems: {
                    w: (w) => w - 100,
                    Items: {
                        flex: {
                            direction: 'column'
                        }
                    },
                    Focus: {
                        rect: true,
                        colorLeft: 4294293565 /* Colors.ACCENT */,
                        colorRight: 4294293565 /* Colors.ACCENT */,
                        x: 40,
                        h: 6,
                        shader: { type: Lightning.shaders.RoundedRectangle, radius: 3 },
                        transitions: {
                            alpha: { duration: 0.3, timingFunction: 'cubic-bezier(0.20, 1.00, 0.80, 1.00)' },
                            w: { duration: 0.3, timingFunction: 'cubic-bezier(0.20, 1.00, 0.80, 1.00)' }
                        }
                    }
                },
                Settings: {
                    y: -50,
                    texture: Lightning.Tools.getSvgTexture('icons/settings.svg', 40, 40)
                }
            }
        };
    }
    _init() {
        this._index = 0;
    }
    _setup() {
        this._items = [
            {
                label: 'Home',
                icon: 'home',
                route: 'home'
            },
            {
                label: 'Live TV',
                icon: 'tv',
                route: 'livetv'
            },
            {
                label: 'Movies & Shows',
                icon: 'movies',
                route: 'movies'
            },
            {
                label: 'Discover',
                icon: 'discover',
                route: 'discover'
            }
        ];
        const items = this._items.map((item) => {
            return {
                type: MenuItem,
                label: item.label,
                selected: false,
                id: item.route,
                icon: item.icon,
                flexItem: { marginBottom: 10 }
            };
        });
        this.tag('MenuItems.Items').add(items);
    }
    get activeItem() {
        return this.tag('Items').children[this._index];
    }
    _handleUp() {
        if (this._index > 0) {
            this._select(-1);
        }
    }
    _handleDown() {
        if (this._index < this.tag('Items').children.length - 1) {
            this._select(1);
        }
    }
    // The Router hands focus back to the page on any key a widget leaves unhandled,
    // so Left must be consumed here or a second Left press would close the menu.
    _handleLeft() { }
    _handleRight() {
        Router.restoreFocus();
    }
    _handleEnter() {
        Router.navigate(`${this.activeItem.id}`, false);
        Router.restoreFocus();
    }
    _focus() {
        const list = this.tag('Items');
        for (let i = 0; i < list.children.length; i++) {
            list.children[i].collapsed = false;
        }
        this.tag('Wrapper').patch({
            smooth: { w: 250, alpha: 0.95 }
        });
        this.tag('ShaderExtra').patch({
            smooth: { x: 270, alpha: 0.95 }
        });
        // this.tag('Logo').collapsed = false;
        this.tag('Logo').patch({
            collapsed: false,
            x: 125
        });
        this.tag('Focus').w = 0;
        this.tag('Focus').setSmooth('alpha', 1);
        this._animateToSelected();
    }
    _unfocus() {
        const list = this.tag('Items');
        this.tag('Wrapper').patch({
            smooth: { w: 50, alpha: 0.8 }
        });
        this.tag('ShaderExtra').patch({
            smooth: { x: 70, alpha: 0.8 }
        });
        this.tag('Logo').patch({
            collapsed: true,
            x: 25
        });
        for (let i = 0; i < list.children.length; i++) {
            list.children[i].collapsed = true;
        }
        this.tag('Focus').setSmooth('alpha', 0);
    }
    _select(direction) {
        this._index += direction;
        if (this._index < this.tag('Items').children.length) {
            this._animateToSelected();
        }
    }
    _animateToSelected() {
        this.tag('Focus').patch({
            smooth: { y: this.activeItem.finalY + 15, w: this.activeItem.finalW }
        });
    }
    _getFocused() {
        return this.activeItem;
    }
    _onActivated(page) {
        const list = this.tag('Items');
        const currentRouteId = page[Router.symbols['route']].toLocaleLowerCase();
        for (let i = 0; i < list.children.length; i++) {
            list.children[i].selected = list.children[i]._id === currentRouteId;
            if (list.children[i]._id === currentRouteId) {
                this._selectedChild = list.children[i];
            }
        }
    }
}
